package com.bank.recon.service;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.logging.Logger;

// Finds all unique quadruplets of amounts that sum to a target.
public class QuadrupleFinder {
    private static final Logger log = Logger.getLogger(QuadrupleFinder.class.getName());

    public List<List<Integer>> findQuadruplets(int[] amounts, int target) {
        List<List<Integer>> result = new ArrayList<>();
        if (amounts == null || amounts.length < 4) return result;

        Arrays.sort(amounts);
        int n = amounts.length;

        for (int i = 0; i < n - 3; i++) {
            if (i > 0 && amounts[i] == amounts[i - 1]) continue; // skip dup first
            for (int j = i + 1; j < n - 2; j++) {
                if (j > i + 1 && amounts[j] == amounts[j - 1]) continue; // skip dup second

                int left = j + 1;
                int right = n - 1;
                while (left < right) {
                    long sum = (long) amounts[i] + amounts[j] + amounts[left] + amounts[right];
                    if (sum == target) {
                        result.add(Arrays.asList(
                                amounts[i], amounts[j], amounts[left], amounts[right]));
                        while (left < right && amounts[left] == amounts[left + 1]) left++;
                        while (left < right && amounts[right] == amounts[right - 1]) right--;
                        left++;
                        right--;
                    } else if (sum < target) {
                        left++;
                    } else {
                        right--;
                    }
                }
            }
        }
        log.info(() -> "Found " + result.size() + " quadruplet(s): " + result);
        return result;
    }
}
