package com.bank.recon;

import com.bank.recon.service.QuadrupleFinder;
import java.util.List;
import java.util.logging.Logger;

public class QuadrupleDemo {
    private static final Logger log = Logger.getLogger(QuadrupleDemo.class.getName());

    public static void main(String[] args) {
        // Transaction amounts (scaled) and the target figure.
        int[] amounts = {1, 0, -1, 0, -2, 2};
        int target = 0;

        QuadrupleFinder finder = new QuadrupleFinder();
        List<List<Integer>> quads = finder.findQuadruplets(amounts, target);

        for (List<Integer> q : quads) {
            log.info(() -> "Quadruple summing to target: " + q);
        }
    }
}
